import{_ as s,o as e,c as a,ag as d}from"./chunks/framework.C9sp7nFj.js";const k=JSON.parse('{"title":"MovLRel 直线相对运动","description":"","frontmatter":{},"headers":[],"relativePath":"3. 指令/1. 运动指令/MovLRel.md","filePath":"3. 指令/1. 运动指令/MovLRel.md","lastUpdated":1778862643000}'),i={name:"3. 指令/1. 运动指令/MovLRel.md"};function n(r,t,o,l,h,p){return e(),a("div",null,[...t[0]||(t[0]=[d(`<h1 id="movlrel-直线相对运动" tabindex="-1">MovLRel 直线相对运动 <a class="header-anchor" href="#movlrel-直线相对运动" aria-label="Permalink to &quot;MovLRel 直线相对运动&quot;">​</a></h1><p>MovLRel 为直线相对运动指令。该指令总是以<strong>当前机器人位置</strong>或<strong>上一步运动指令的目标位置</strong>为起点，然后机器人根据设定的增量进行位置偏移或姿态偏移。</p><h2 id="指令格式" tabindex="-1">指令格式 <a class="header-anchor" href="#指令格式" aria-label="Permalink to &quot;指令格式&quot;">​</a></h2><p>MovLRel(P, T, [V], [B], [C], [PayLoad], [O], [DO])</p><p>MovLRel(相对增量点, 目标点, [速度], [平滑], [姿态], [负载], [姿态控制], [端口输出])</p><p><em>(备注：带 [] 参数为可选参数)</em></p><hr><h2 id="参数详细说明" tabindex="-1">参数详细说明 <a class="header-anchor" href="#参数详细说明" aria-label="Permalink to &quot;参数详细说明&quot;">​</a></h2><table tabindex="0"><thead><tr><th>参数</th><th>类型</th><th>说明</th><th>默认值/备注</th></tr></thead><tbody><tr><td>P</td><td>DCPOS 变量</td><td>执行该指令时机器人要移动的位置增量（dx, dy, dz, da, db, dc）。</td><td>必填</td></tr><tr><td>T</td><td>enum（COORD / TOOL）</td><td>设置相对位移参照的坐标系：<br><code>COORD</code>：参考当前笛卡尔坐标系（基坐标系或用户坐标系）。<br><code>TOOL</code>：参考当前工具坐标系。</td><td>必填</td></tr><tr><td>[V]</td><td>SPEED 变量</td><td>指定直线运动速度。SPEED 变量中的 <code>tcp</code>（平移）和 <code>ori</code>（旋转）分量有效；有外部轴时，<code>exj_l</code>、<code>exj_r</code> 有效。</td><td>可选，默认 V4000</td></tr><tr><td>[B]</td><td>enum（FINE / RELATIVE / ABSOLUTE / DEFAULT）</td><td>机器人逼近终点时的过渡方式（无过渡、相对、绝对、缺省）。</td><td>可选，默认 FINE</td></tr><tr><td>[C]</td><td>ZONE 变量</td><td>机器人逼近终点时的过渡半径/数值。</td><td>可选，默认 C100</td></tr><tr><td>[PayLoad]</td><td>PAYLOAD 变量</td><td>机器人执行该轨迹时使用的负载参数。</td><td>可选，默认使用当前系统中设置的负载</td></tr><tr><td>[O]</td><td>enum（GOVRON / GOVROFF）</td><td><code>GOVRON</code>：受全局速度倍率影响。<br><code>GOVROFF</code>：不受全局速度倍率影响。</td><td>可选，默认 GOVRON</td></tr><tr><td>[DO]</td><td>string</td><td>指令执行完后触发的 IO 操作（如 <code>SetDO</code>、<code>PulseOut</code> 等）。</td><td>可选</td></tr></tbody></table><hr><h2 id="应用示例" tabindex="-1">应用示例 <a class="header-anchor" href="#应用示例" aria-label="Permalink to &quot;应用示例&quot;">​</a></h2><p><strong>示例 1：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(P1, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovLRel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DCPOS0, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;COORD&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>机器人以 50 的速度直线运动到 P1 点，随后在 P1 点的基础上，参考笛卡尔坐标系，按 <code>DCPOS0</code> 中的距离增量进行直线偏移运动。</p><p><strong>示例 2：</strong></p><div class="language-estun vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">estun</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">MovLRel</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (DCPOS0, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;TOOL&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, V50, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;RELATIVE&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, C100)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>机器人以 50 的速度，从<strong>当前点</strong>出发，参考<strong>工具坐标系</strong>（如沿工具 Z 轴方向）相对运动 <code>DCPOS0</code> 中的位移距离。</p>`,17)])])}const E=s(i,[["render",n]]);export{k as __pageData,E as default};
